import {readFileSync} from 'node:fs';import {resolve} from 'node:path';import {createHash} from 'node:crypto';
const root=resolve('physics'),run='physics-em-sr-40-2026-10-08';let n=0;
for(const u of [1,2,3]){const report=JSON.parse(readFileSync(`${root}/research/${run}-step7-v2/step7-v2-gate-r1-u${u}.json`,'utf8'));for(const [path,hash] of Object.entries(report.supporting_evidence??{})){if(!resolve(path).startsWith(resolve(root,'research')+'/')||!/^[a-f0-9]{64}$/.test(hash))throw Error('invalid supporting evidence path or hash: '+path);if(createHash('sha256').update(readFileSync(path,'utf8')).digest('hex')!==hash)throw Error('evidence changed: '+path);n++;}}
console.log(`Exact native resolve/hash expressions passed for ${n} supporting evidence entry across 3 uncollected gate reports.`);
